import styled from "styled-components";

function Profile() {
  return (
    <Wrap>
      <Top>
        <Avatar />
        <Info>
          <h3>김연재</h3>
          <p>100 팔로워 · 10 팔로잉</p>
        </Info>
      </Top>

      <Bubble>
        예시를 좋아하는 책린이 입니다!
      </Bubble>

      {/* 책장 */}
      <Shelf>
        <Book />
        <Book />
        <Book />
        <Book />
        <Book />
      </Shelf>
    </Wrap>
  );
}

export default Profile;

/* ===== styled ===== */

const Wrap = styled.div`
  padding: 15px;
  background: #F6FBF2;
`;

const Top = styled.div`
  display: flex;
  gap: 10px;
  align-items: center;
`;

const Avatar = styled.div`
  width: 60px;
  height: 60px;
  border-radius: 50%;
  background: #ccc;
`;

const Info = styled.div`
  p {
    font-size: 12px;
    color: gray;
  }
`;

const Bubble = styled.div`
  margin-top: 15px;
  padding: 10px;
  background: white;
  border-radius: 20px;
  font-size: 13px;
`;

const Shelf = styled.div`
  margin-top: 20px;
  display: flex;
  flex-direction: column;
  gap: 10px;
`;

const Book = styled.div`
  height: 55px;
  background: white;
  border-radius: 12px;
  border-left: 6px solid #8BC34A;
`;
